import { describe, expect, it } from 'vitest';
import { Add, Float, Mul, Pow, Rational, continuedFraction, continuedFractionConvergents, continuedFractionIterator, continuedFractionPeriodic, continuedFractionReduce, expand, pi } from '../../src';
import { pyItems, sympyStr } from '../sympy-str';

describe("doctests of sympy.ntheory.continued_fraction", () => {
  // a primitive result that no library call returned
  //   continued_fraction((1 + 2*sqrt(3))/5)
  //   => [0, 1, [8, 3, 34, 3]]
  it.todo("continued_fraction((1 + 2*sqrt(3))/5)");
  // a primitive result that no library call returned
  //   continued_fraction_periodic(3, 2, 7)
  //   => [2, [1, 4, 1, 1]]
  it.todo("continued_fraction_periodic(3, 2, 7)");
  // a primitive result that no library call returned
  //   continued_fraction_periodic(1, 2, 5)
  //   => [[1]]
  it.todo("continued_fraction_periodic(1, 2, 5)");
  // a primitive result that no library call returned
  //   continued_fraction_periodic(4, 3, 0)
  //   => [1, 3]
  it.todo("continued_fraction_periodic(4, 3, 0)");
  // a primitive result that no library call returned
  //   continued_fraction_periodic(4, 3, 49)
  //   => [3, 1, 2]
  it.todo("continued_fraction_periodic(4, 3, 49)");
  it("continued_fraction_reduce([1, 2, 3, 4, 5])", () => {
    expect(sympyStr(continuedFractionReduce([1, 2, 3, 4, 5]))).toBe('225/157');
  });
  it("continued_fraction_reduce([-2, 1, 9, 7, 1, 2])", () => {
    expect(sympyStr(continuedFractionReduce([-2, 1, 9, 7, 1, 2]))).toBe('-256/233');
  });
  it("continued_fraction_reduce([2, 1, 2, 1, 1, 4, 1, 1, 6, 1, 1, 8]).n(10)", () => {
    expect(sympyStr(Rational.of(23225n, 8544n, { gcd: 1n }).evalf(10, {}))).toBe('2.718281835');
  });
  it("continued_fraction_reduce([1, 4, 2, [3, 1]])", () => {
    expect(sympyStr(continuedFractionReduce([1, 4, 2, [3, 1]]))).toBe('(sqrt(21) + 287)/238');
  });
  it("continued_fraction_reduce([[1]])", () => {
    expect(sympyStr(continuedFractionReduce([[1]]))).toBe('(1 + sqrt(5))/2');
  });
  it("continued_fraction_reduce(continued_fraction_periodic(8, 5, 13))", () => {
    expect(sympyStr(continuedFractionReduce([2, [3, 8, 1]]))).toBe('(sqrt(13) + 8)/5');
  });
});

